<template>
  <div><Login v-if="!sesionIniciada" @login-exitoso="iniciarSesion" /><div v-else class="min-vh-100 bg-light"><header class="bg-csc-orange shadow-sm mb-4"><div class="container py-3 d-flex justify-content-between align-items-center"><div><h3 class="fw-bold mb-0 text-white">Caja de Salud de Caminos</h3><p class="small mb-0 text-white-50">Sistema de Control e Inventario de Almacén</p></div><div class="text-end text-white"><small>{{ usuarioActual.nombre }} ({{ usuarioActual.rol }})</small><br><button class="btn btn-light btn-sm mt-1" @click="cerrarSesion">Salir</button></div></div></header><main class="container py-2"><nav class="nav nav-pills gap-2 mb-4 p-2 bg-white rounded-3 shadow-sm"><button v-if="puedeModificar" class="nav-link fw-bold" :class="vistaActual === 'ingreso' ? 'bg-csc-orange text-white' : 'text-secondary'" @click="vistaActual = 'ingreso'">Registrar ingreso</button><button v-if="puedeModificar" class="nav-link fw-bold" :class="vistaActual === 'salida' ? 'bg-csc-orange text-white' : 'text-secondary'" @click="vistaActual = 'salida'">Registrar salida</button><button class="nav-link fw-bold" :class="vistaActual === 'inventario' ? 'bg-csc-orange text-white' : 'text-secondary'" @click="vistaActual = 'inventario'">Ver inventario</button></nav><RegistrarIngreso v-if="vistaActual === 'ingreso' && puedeModificar" :recibido-por="usuarioActual.nombre" /><RegistrarSalida v-if="vistaActual === 'salida' && puedeModificar" /><Inventario v-if="vistaActual === 'inventario'" /></main></div></div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import Login from './components/Login.vue'; import Inventario from './components/Inventario.vue'; import RegistrarSalida from './components/RegistrarSalida.vue'; import RegistrarIngreso from './components/RegistrarIngreso.vue';
const sesionIniciada = ref(false), usuarioActual = ref({ nombre: '', rol: '' }), vistaActual = ref('ingreso'); const puedeModificar = computed(() => ['almacen','auxiliar','admin'].includes(usuarioActual.value.rol)); onMounted(() => { const u = localStorage.getItem('usuario_actual'), t = localStorage.getItem('auth_token'); if (u && t) { usuarioActual.value = JSON.parse(u); sesionIniciada.value = true; } }); const iniciarSesion = datos => { usuarioActual.value = datos; sesionIniciada.value = true; }; const cerrarSesion = () => { localStorage.removeItem('auth_token'); localStorage.removeItem('usuario_actual'); sesionIniciada.value = false; };
</script>
<style>.bg-csc-orange{background-color:#e85d04!important;color:#fff!important}.text-csc-orange{color:#e85d04!important}.btn-csc-orange{background-color:#e85d04;color:#fff;border:0}.btn-csc-orange:hover{background-color:#dc2f02;color:#fff}.bg-soft-blue{background-color:#e3f2fd!important}.text-primary{color:#1976d2!important}</style>
